      method: 'POST',
      body: { username, password },
    });
    return session;
  }

  /** Exchange a stale token for a fresh one once it expires. */
  async refreshToken(sessionId: string): Promise<Session> {
    return this.client.request<Session>({ path: `auth/${sessionId}/refresh` });
